package dev.myjarvis.core;

import jakarta.servlet.http.Cookie;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

class ConversationDeletionHttpTest {
    private MockMvc http;private ConversationDeletionService deletion;private AuthService auth;private AuthService.Session session;private UUID target;private Cookie cookie;
    @BeforeEach void setup(){auth=mock(AuthService.class);deletion=mock(ConversationDeletionService.class);session=new AuthService.Session("fixture-hash",UUID.randomUUID(),Instant.now(),1);target=UUID.randomUUID();cookie=new Cookie(WebSecurity.COOKIE,"fixture-cookie");when(auth.find("fixture-cookie")).thenReturn(session);when(auth.csrf(eq(session),eq("fixture-csrf"))).thenReturn(true);http=MockMvcBuilders.standaloneSetup(new ConversationDeletionController(deletion)).setControllerAdvice(new ApiErrors()).addFilters(new WebSecurity(auth,"https://localhost:8443",false)).build();}
    private String preparePath(){return "/api/v1/conversations/"+target+"/delete-preparations";}
    @Test void stateAndReceiptReadsHaveNoStoreAndRejectEveryQueryOrBody() throws Exception {when(deletion.state(session,target)).thenReturn(Map.of("status","DELETED","conversation_id",target,"deletion_id",UUID.randomUUID(),"deleted_at","2026-10-10T00:00:00Z","checked_at","2026-10-10T00:00:00Z"));String path="/api/v1/conversations/"+target+"/deletion-state";var result=http.perform(get(path).cookie(cookie)).andReturn().getResponse();assertEquals(200,result.getStatus());assertEquals("no-store",result.getHeader("Cache-Control"));assertEquals("nosniff",result.getHeader("X-Content-Type-Options"));clearInvocations(deletion);for(String query:List.of("?x=1","?limit=1","?owner_id="+session.owner()))assertEquals(400,http.perform(get(path+query).cookie(cookie)).andReturn().getResponse().getStatus());assertEquals(400,http.perform(get(path).cookie(cookie).content("{}" )).andReturn().getResponse().getStatus());assertEquals(400,http.perform(get("/api/v1/conversation-deletions/requests/"+UUID.randomUUID()+"?retry=true").cookie(cookie)).andReturn().getResponse().getStatus());verifyNoInteractions(deletion);}
    @Test void missingAuthenticationCsrfOriginAndNonJsonFailBeforeService() throws Exception {String body="{\"expected_version\":1,\"expected_digest\":\""+"a".repeat(64)+"\"}";assertEquals(401,http.perform(get("/api/v1/conversations/"+target+"/deletion-state")).andReturn().getResponse().getStatus());assertEquals(403,http.perform(post(preparePath()).cookie(cookie).contentType("application/json").content(body)).andReturn().getResponse().getStatus());assertEquals(403,http.perform(post(preparePath()).cookie(cookie).header("Origin","https://localhost:8443").contentType("application/json").content(body)).andReturn().getResponse().getStatus());assertEquals(415,http.perform(post(preparePath()).cookie(cookie).header("Origin","https://localhost:8443").header("X-CSRF-Token","fixture-csrf").contentType("text/plain").content(body)).andReturn().getResponse().getStatus());verifyNoInteractions(deletion);}
    @Test void exactlyOneCanonicalIdempotencyKeyAndNoQueryAreRequired() throws Exception {String body="{}";for(String key:List.of("not-a-uuid",UUID.randomUUID().toString().toUpperCase())){assertEquals(400,http.perform(post(preparePath()).cookie(cookie).header("Origin","https://localhost:8443").header("X-CSRF-Token","fixture-csrf").header("Idempotency-Key",key).contentType("application/json").content(body)).andReturn().getResponse().getStatus());}assertEquals(400,http.perform(post(preparePath()).cookie(cookie).header("Origin","https://localhost:8443").header("X-CSRF-Token","fixture-csrf").header("Idempotency-Key",UUID.randomUUID(),UUID.randomUUID()).contentType("application/json").content(body)).andReturn().getResponse().getStatus());assertEquals(400,http.perform(post(preparePath()+"?x=1").cookie(cookie).header("Origin","https://localhost:8443").header("X-CSRF-Token","fixture-csrf").header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body)).andReturn().getResponse().getStatus());verifyNoInteractions(deletion);}
    @Test void duplicateKeysMalformedUtf8FloatingValuesAndLoneSurrogatesAreRejected() throws Exception {for(String body:List.of("{\"expected_version\":1,\"expected_version\":2}","{\"expected_version\":1.0}","{\"payload_hash\":\"\\ud800\"}","{\"expected_version\":9007199254740992}")){assertEquals(400,http.perform(post(preparePath()).cookie(cookie).header("Origin","https://localhost:8443").header("X-CSRF-Token","fixture-csrf").header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body)).andReturn().getResponse().getStatus());}verifyNoInteractions(deletion);}
    @Test void committedConfirmUsesClosedEnvelopeAndServiceOwnsCommitBoundary() throws Exception {UUID preparation=UUID.randomUUID(),key=UUID.randomUUID();when(deletion.confirm(eq(session),eq(key),eq(preparation),any())).thenReturn(Map.of("status","COMMITTED","receipt",Map.of("deletion_id",UUID.randomUUID(),"conversation_id",target,"preparation_id",preparation,"scope_policy","CONVERSATION_SOURCE_V1","deleted_version",1,"tombstone_version",2,"deleted_at","2026-10-10T00:00:00Z"),"checked_at","2026-10-10T00:00:00Z"));var response=http.perform(post("/api/v1/conversation-delete-preparations/"+preparation+"/confirm").cookie(cookie).header("Origin","https://localhost:8443").header("X-CSRF-Token","fixture-csrf").header("Idempotency-Key",key).contentType("application/json").content("{\"payload_hash\":\""+"a".repeat(64)+"\",\"expected_version\":1,\"expected_digest\":\""+"b".repeat(64)+"\",\"confirm\":true}")).andReturn().getResponse();assertEquals(200,response.getStatus());var body=Json.parse(response.getContentAsByteArray());assertEquals("COMMITTED",body.path("data").path("status").asText());assertTrue(body.has("request_id"));}
}
